const globalStore = $getWorkflowStaticData('global');
const payload = $input.first().json.body ?? $input.first().json;
const rows = Array.isArray(payload.rows) ? payload.rows : [];
const uploadedAt = payload.uploaded_at || new Date().toISOString();
const normalizedRows = rows.map((row, index) => ({
  leadId: row.leadId || row.lead_id || row.id || `MHD-${String(index + 1).padStart(3, '0')}`,
  serialNo: row.serialNo || row.serial_no || row['S. No'] || String(index + 1),
  supplierName: row.supplierName || row.supplier_name || 'Mahindra Supplier',
  pocName: row.pocName || row.poc_name || 'Supplier POC',
  phone: row.phone || '',
  email: row.email || '',
  partNo: row.partNo || row.part_no || '',
  partDescription: row.partDescription || row.part_description || '',
  addValue: row.addValue || row.add || '',
  currentCoverageDays: row.currentCoverageDays || row.current_coverage_days || '',
  qtyRequired: row.qtyRequired || row.qty_required || '',
  qtyRequiredDate: row.qtyRequiredDate || row.qty_required_date || '',
  qtyRequiredTime: row.qtyRequiredTime || row.qty_required_time || '',
  qtyConfirmed: row.qtyConfirmed || row.qty_confirmed || '',
  dateConfirmed: row.dateConfirmed || row.date_confirmed || '',
  status: row.status || 'Pending',
  reasonForDelay: row.reasonForDelay || row.reason_for_delay || '',
  vehicleDetails: row.vehicleDetails || row.vehicle_details || '',
  driverDetails: row.driverDetails || row.driver_details || '',
  riskLevel: row.riskLevel || row.risk_level || 'LOW',
  emailRecipients: row.emailRecipients || row.email_recipients || payload.default_email_recipients || 'mahindra-demo@procure-os.local',
  source: payload.filename || 'manual-upload',
  lastUpdatedAt: uploadedAt
}));
globalStore.mahindraRows = normalizedRows;
globalStore.lastUpload = {
  filename: payload.filename || 'manual-upload',
  rowCount: normalizedRows.length,
  uploadedAt
};
return [{ json: { success: true, rowCount: normalizedRows.length, uploadedAt, filename: globalStore.lastUpload.filename } }];

const globalStore = $getWorkflowStaticData('global');
const rows = globalStore.mahindraRows || [];
return [{ json: { rows } }];

const globalStore = $getWorkflowStaticData('global');
const body = $input.first().json.body ?? $input.first().json;
const rows = Array.isArray(globalStore.mahindraRows) ? globalStore.mahindraRows : [];
const toNumber = (value) => {
  const numeric = Number(String(value ?? '').replace(/,/g, '').trim());
  return Number.isFinite(numeric) ? numeric : null;
};
const parseDate = (value) => {
  const raw = String(value || '').trim().replace(/\./g, '-').replace(/\//g, '-');
  if (!raw) return null;
  const match = raw.match(/^(\d{1,2})-(\d{1,2})-(\d{2,4})$/);
  if (match) {
    const [, day, month, year] = match;
    const fullYear = year.length === 2 ? `20${year}` : year;
    const parsed = new Date(`${fullYear}-${month.padStart(2, '0')}-${day.padStart(2, '0')}T00:00:00`);
    return Number.isNaN(parsed.getTime()) ? null : parsed;
  }
  const parsed = new Date(raw);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
};
const computeRisk = (row) => {
  const coverage = toNumber(row.currentCoverageDays);
  const requiredQty = toNumber(row.qtyRequired);
  const confirmedQty = toNumber(row.qtyConfirmed);
  const requiredDate = parseDate(row.qtyRequiredDate);
  const confirmedDate = parseDate(row.dateConfirmed);
  if (String(row.status || '').toLowerCase() === 'delayed') return 'CRITICAL';
  if (coverage !== null && coverage <= 2) return 'CRITICAL';
  if (requiredQty !== null && confirmedQty !== null && confirmedQty < requiredQty) return 'CRITICAL';
  if (requiredDate && confirmedDate && confirmedDate > requiredDate) return 'CRITICAL';
  return 'LOW';
};
const leadId = body.leadId || body.lead_id;
const existing = rows.find((row) => row.leadId === leadId) || {};
const updated = {
  ...existing,
  ...body,
  leadId,
  status: body.status || existing.status || 'Pending',
  qtyConfirmed: body.qtyConfirmed || existing.qtyConfirmed || '',
  dateConfirmed: body.dateConfirmed || existing.dateConfirmed || '',
  reasonForDelay: body.reasonForDelay || existing.reasonForDelay || '',
  vehicleDetails: body.vehicleDetails || existing.vehicleDetails || '',
  driverDetails: body.driverDetails || existing.driverDetails || '',
  emailRecipients: body.emailRecipients || existing.emailRecipients || 'mahindra-demo@procure-os.local',
  lastUpdatedAt: new Date().toISOString()
};
updated.riskLevel = body.riskLevel || computeRisk(updated);
globalStore.mahindraRows = rows.some((row) => row.leadId === leadId)
  ? rows.map((row) => row.leadId === leadId ? updated : row)
  : [...rows, updated];
return [{ json: updated }];

